() => {
  const canvas = document.querySelector('canvas');
  // Walk up the fiber tree from canvas to find any R3F context
  const fiberKey = Object.keys(canvas).find(k => k.startsWith('__reactFiber'));
  if (!fiberKey) return 'no fiber';
  let fiber = canvas[fiberKey];
  // Walk up to find the root or any fiber with __r3f or stateNode with __r3f
  let depth = 0;
  const r3fPaths = [];
  while (fiber && depth < 100) {
    if (fiber.stateNode && fiber.stateNode.__r3f) {
      r3fPaths.push({ depth, type: fiber.type?.name || fiber.type || String(fiber.type), has: '__r3f on stateNode' });
    }
    if (fiber.memoizedState) {
      // Check if zustand store is in memoized state
      let ms = fiber.memoizedState;
      let msDepth = 0;
      while (ms && msDepth < 10) {
        if (ms.queue && ms.queue.lastRenderedState && ms.queue.lastRenderedState.scene) {
          return { found: 'zustand store in fiber', depth, frameloop: ms.queue.lastRenderedState.frameloop };
        }
        ms = ms.next;
        msDepth++;
      }
    }
    fiber = fiber.return;
    depth++;
  }
  return { r3fPaths, walkedDepth: depth };
}

