() => {
  const canvas = document.querySelector('canvas');
  if (!canvas) return 'no canvas';
  // Simulate mouse events to trigger orbit controls
  const rect = canvas.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  // mousedown at center
  canvas.dispatchEvent(new PointerEvent('pointerdown', { clientX: cx, clientY: cy, bubbles: true, button: 0 }));
  // move
  canvas.dispatchEvent(new PointerEvent('pointermove', { clientX: cx + 50, clientY: cy + 50, bubbles: true }));
  canvas.dispatchEvent(new PointerEvent('pointermove', { clientX: cx + 100, clientY: cy + 100, bubbles: true }));
  // up
  canvas.dispatchEvent(new PointerEvent('pointerup', { clientX: cx + 100, clientY: cy + 100, bubbles: true, button: 0 }));
  return 'dispatched pointer events';
}

