const Gizmo: React.FC<GizmoProps> = ({ show = true, onAxisClick }) => {
  const [colors, setColors] = React.useState<[string, string, string]>(() => [getComputedColor("--accent"), getComputedColor("--accent-tertiary"), getComputedColor("--accent-secondary")]);
  const labelColor = React.useMemo(() => getComputedColor("--foreground"), []);
  const { gl, camera, size, invalidate } = useThree();

  const gizmoRef = React.useRef<{
    scene: THREE.Scene;
    camera: THREE.OrthographicCamera;
    group: THREE.Group;
    axisX: THREE.Mesh;
    axisY: THREE.Mesh;
    axisZ: THREE.Mesh;
    headX: THREE.Sprite;
    headY: THREE.Sprite;
    headZ: THREE.Sprite;
  } | null>(null);

  React.useEffect(() => {
    const updateColors = () => setColors([getComputedColor("--accent"), getComputedColor("--accent-tertiary"), getComputedColor("--accent-secondary")]);
    updateColors();
    const observer = new MutationObserver(updateColors);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    return () => observer.disconnect();
  }, []);

  // Initialize the gizmo scene imperatively
  React.useMemo(() => {
    if (gizmoRef.current) return;
    const scene = new THREE.Scene();
    const cam = new THREE.OrthographicCamera(-1, 1, 1, -1, -1000, 1000);
    cam.position.set(0, 0, 200);

    const group = new THREE.Group();
    scene.add(group);

    const axisGroup = new THREE.Group();
    axisGroup.scale.setScalar(40);
    group.add(axisGroup);

    // Create axes with box geometry
    const createAxis = (color: string, rotation: [number, number, number]): THREE.Mesh => {
      const geo = new THREE.BoxGeometry(0.8, 0.05, 0.05);
      const mat = new THREE.MeshBasicMaterial({ color, toneMapped: false });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(0.4, 0, 0);
      const wrapper = new THREE.Group();
      wrapper.rotation.set(...rotation);
      wrapper.add(mesh);
      axisGroup.add(wrapper);
      return mesh;
    };

    const axisX = createAxis("#ff2060", [0, 0, 0]);
    const axisY = createAxis("#20df80", [0, 0, Math.PI / 2]);
    const axisZ = createAxis("#2080ff", [0, -Math.PI / 2, 0]);

    // Create axis head sprites
    const createHeadTexture = (arcColor: string, label: string, lColor: string): THREE.CanvasTexture => {
      const canvas = document.createElement("canvas");
      canvas.width = 64;
      canvas.height = 64;
      const ctx = canvas.getContext("2d")!;
      ctx.beginPath();
      ctx.arc(32, 32, 16, 0, 2 * Math.PI);
      ctx.closePath();
      ctx.fillStyle = arcColor;
      ctx.fill();
      if (label) {
        ctx.font = "18px Inter var, Arial, sans-serif";
        ctx.textAlign = "center";
        ctx.fillStyle = lColor;
        ctx.fillText(label, 32, 41);
      }
      return new THREE.CanvasTexture(canvas);
    };

    const createHead = (arcColor: string, label: string, lColor: string, pos: [number, number, number]): THREE.Sprite => {
      const tex = createHeadTexture(arcColor, label, lColor);
      const mat = new THREE.SpriteMaterial({ map: tex, alphaTest: 0.3, opacity: 1, toneMapped: false });
      const sprite = new THREE.Sprite(mat);
      sprite.position.set(...pos);
      axisGroup.add(sprite);
      return sprite;
    };

    const headX = createHead("#ff2060", "X", "#000", [1, 0, 0]);
    const headY = createHead("#20df80", "Z", "#000", [0, 1, 0]);
    const headZ = createHead("#2080ff", "-Y", "#000", [0, 0, 1]);

    gizmoRef.current = { scene, camera: cam, group, axisX, axisY, axisZ, headX, headY, headZ };
  }, []);

  // Update colors when they change
  React.useEffect(() => {
    if (!gizmoRef.current) return;
    const [colorX, colorY, colorZ] = colors;
    (gizmoRef.current.axisX.material as THREE.MeshBasicMaterial).color.set(colorX);
    (gizmoRef.current.axisY.material as THREE.MeshBasicMaterial).color.set(colorY);
    (gizmoRef.current.axisZ.material as THREE.MeshBasicMaterial).color.set(colorZ);

    // Update head sprites
    const updateHead = (sprite: THREE.Sprite, arcColor: string, label: string, lColor: string) => {
      const canvas = document.createElement("canvas");
      canvas.width = 64;
      canvas.height = 64;
      const ctx = canvas.getContext("2d")!;
      ctx.beginPath();
      ctx.arc(32, 32, 16, 0, 2 * Math.PI);
      ctx.closePath();
      ctx.fillStyle = arcColor;
      ctx.fill();
      if (label) {
        ctx.font = "18px Inter var, Arial, sans-serif";
        ctx.textAlign = "center";
        ctx.fillStyle = lColor;
        ctx.fillText(label, 32, 41);
      }
      const tex = new THREE.CanvasTexture(canvas);
      (sprite.material as THREE.SpriteMaterial).map?.dispose();
      (sprite.material as THREE.SpriteMaterial).map = tex;
      (sprite.material as THREE.SpriteMaterial).needsUpdate = true;
    };
    updateHead(gizmoRef.current.headX, colorX, "X", labelColor);
    updateHead(gizmoRef.current.headY, colorY, "Z", labelColor);
    updateHead(gizmoRef.current.headZ, colorZ, "-Y", labelColor);
    invalidate();
  }, [colors, labelColor, invalidate]);

  // Update camera frustum when size changes
  React.useEffect(() => {
    if (!gizmoRef.current) return;
    const cam = gizmoRef.current.camera;
    cam.left = -size.width / 2;
    cam.right = size.width / 2;
    cam.top = size.height / 2;
    cam.bottom = -size.height / 2;
    cam.updateProjectionMatrix();

    // Position gizmo in bottom-right corner
    const margin = 80;
    const x = size.width / 2 - margin;
    const y = -size.height / 2 + margin;
    gizmoRef.current.group.position.set(x, y, 0);
    invalidate();
  }, [size, invalidate]);

  // Render the gizmo scene on top of the main scene in useFrame
  const matrixRef = React.useRef(new THREE.Matrix4());
  useFrame(({ scene: mainScene }) => {
    if (!gizmoRef.current || !show) return;
    // Sync gizmo orientation with main camera
    matrixRef.current.copy(camera.matrix).invert();
    gizmoRef.current.group.quaternion.setFromRotationMatrix(matrixRef.current);

    // Render main scene first
    const oldClear = gl.autoClear;
    gl.autoClear = true;
    gl.render(mainScene, camera);

    // Then render gizmo scene on top
    gl.autoClear = false;
    gl.clearDepth();
    gl.render(gizmoRef.current.scene, gizmoRef.current.camera);

    gl.autoClear = oldClear;
  }, 1);

  // Cleanup on unmount
  React.useEffect(() => {
    return () => {
      if (gizmoRef.current) {
        gizmoRef.current.scene.traverse((obj) => {
          if (obj instanceof THREE.Mesh) {
            obj.geometry.dispose();
            if (obj.material instanceof THREE.Material) obj.material.dispose();
          }
          if (obj instanceof THREE.Sprite) {
            (obj.material as THREE.SpriteMaterial).map?.dispose();
            (obj.material as THREE.SpriteMaterial).dispose();
          }
        });
      }
    };
  }, []);

  return null;
};

